using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;
public static class NWDrop {
 public static IEnumerator Run(NWProbe p){yield return p.Wait(()=>GameEntry.Instance!=null,15);GameEntry.Instance.Refresh();p.Check("drop-real-continue",GameEntry.Instance.Continue());yield return p.Wait(()=>UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Saves?.IsInitialized==true&&UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.WorldReady==true&&UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Flow?.ActiveRun!=null,30);var s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();if(s==null||!s.WorldReady)throw new Exception("No ready formal Run");foreach(var e in s.enemies){e.enabled=false;var b=e.GetComponent<ForestBossBrain>();if(b!=null)b.enabled=false;}var h=s.hero;var c=h.GetComponent<AdventureCombat>();var run=s.Flow.ActiveRun;var target=s.enemies.FirstOrDefault(e=>!e.Health.Dead&&e.GetComponent<ForestBossBrain>()==null&&NewWeaponDrop.Preview(run,e.entityId,e.archetype)!=null);bool synthetic=target==null;if(synthetic){string id=Enumerable.Range(0,10000).Select(i=>"controlled-drop-fixture-"+i).First(x=>NewWeaponDrop.Preview(run,x,EnemyArchetype.Melee)!=null);var obj=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("CP05Training/Enemy"));UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(obj,h.gameObject.scene);target=obj.GetComponent<CombatEnemy>();target.entityId=id;target.target=h;target.archetype=EnemyArchetype.Melee;target.enabled=false;}p.Check("drop-context-formal",h.GetComponent<CP05TrainingMarker>()==null&&TrainingLootContext.ForDeath(target)==null,"controlled synthetic encounter="+synthetic+"; no claim of normal AI run");var expected=NewWeaponDrop.Preview(run,target.entityId,target.archetype);var cc=target.GetComponent<CharacterController>();cc.enabled=false;target.transform.position=h.transform.position+h.transform.forward*1.4f;cc.enabled=true;PlayerInput.Focus(true);yield return null;yield return null;int attacks=0;while(!target.Health.Dead&&attacks<8){p.Check("drop-actual-strike-"+attacks,c.Strike());attacks++;yield return new WaitForSeconds(c.BasicInterval+.1f);}p.Check("drop-real-death",target.Health.Dead&&target.Health.TotalDamageTaken>0);target.enabled=true;yield return null;yield return null;var drops=UnityEngine.Object.FindObjectsByType<LootPickup>().Where(x=>x.Gear?.id==expected.id).ToArray();p.Check("drop-normal-path-new-gear",drops.Length==1&&JsonUtility.ToJson(drops[0].Gear)==JsonUtility.ToJson(expected));string streams=JsonUtility.ToJson(run.randomStreams);int count=UnityEngine.Object.FindObjectsByType<LootPickup>().Length;target.DropLootOnce();target.DropLootOnce();p.Check("drop-once-no-extra-rng",UnityEngine.Object.FindObjectsByType<LootPickup>().Length==count&&JsonUtility.ToJson(run.randomStreams)==streams);p.Check("drop-ground-not-credited",!c.Gear.items.Any(x=>x.id==expected.id)&&!s.Flow.Profile.warehouse.Any(x=>x.id==expected.id));File.WriteAllText(p.Root+"/drop-context.json",JsonUtility.ToJson(new Context{run=run.runId,entity=target.entityId,content=run.contentRevision,syntheticEncounter=synthetic,expected=expected},true));
 }
 [Serializable]class Context{public string run,entity,content;public bool syntheticEncounter;public GearItem expected;}
}
